/**
 * Acceptance tests from the VERITAS spec §5.1, run against REAL engine output
 * captured from c2pa-rs (fixtures/reports, regenerated by scripts/capture-reports.cjs).
 */
import { readFileSync } from 'fs';
import { join } from 'path';
import { classify, type EngineResponse } from '../classify';

const load = (name: string): EngineResponse =>
  JSON.parse(readFileSync(join(__dirname, '../../../../fixtures/reports', name + '.json'), 'utf8'));

describe('Content Credentials classification (test trust anchors)', () => {
  test('valid AI credential shows an accurate AI declaration', () => {
    const c = classify(load('test--generated--ai-declared.jpg'));
    expect(c.verdict).toBe('ai_declared');
    expect(c.origin).toBe('ai');
    expect(c.trustSource).toBe('test');
    expect(c.checks.find((x) => x.id === 'integrity')?.state).toBe('pass');
  });

  test('valid camera credential does not claim the scene is true', () => {
    const c = classify(load('test--generated--camera-capture.jpg'));
    expect(c.verdict).toBe('capture_declared');
    expect(c.summary).toMatch(/not that the scene is true/);
    expect(c.headline).not.toMatch(/real|authentic|genuine|true/i);
  });

  test('tampered file fails validation', () => {
    const c = classify(load('test--generated--ai-declared-tampered.jpg'));
    expect(c.verdict).toBe('credentials_invalid');
    expect(c.failureCodes).toContain('assertion.dataHash.mismatch');
    expect(c.checks.find((x) => x.id === 'integrity')?.state).toBe('fail');
  });
});

describe('Content Credentials classification (production trust lists)', () => {
  test('unsigned file is "origin unknown", never real or fake', () => {
    for (const f of ['prod--generated--no-credentials.jpg', 'prod--c2pa-rs--sample1.png', 'prod--c2pa-rs--sample1.wav', 'prod--c2pa-rs--sample1.mp3']) {
      const c = classify(load(f));
      expect(c.verdict).toBe('no_credentials');
      expect(c.headline).toBe('Origin unknown');
      expect(`${c.headline} ${c.summary}`).not.toMatch(/(?<!not mean it )\b(is|looks) (real|fake|genuine|authentic)\b/i);
    }
  });

  test('test-certificate signatures are not trusted in production', () => {
    const c = classify(load('prod--generated--ai-declared.jpg'));
    expect(c.verdict).toBe('signer_unrecognized');
    expect(c.trustSource).toBeNull();
    expect(c.summary).toMatch(/Generated by AI/);
  });

  test('forged signature fails validation', () => {
    const c = classify(load('prod--c2pa-rs--E-sig-CA.jpg'));
    expect(c.verdict).toBe('credentials_invalid');
    expect(c.checks.find((x) => x.id === 'signature')?.state).toBe('fail');
  });

  test('altered pixels fail validation', () => {
    expect(classify(load('prod--c2pa-rs--XCA.jpg')).verdict).toBe('credentials_invalid');
  });

  test('video credentials are read', () => {
    expect(classify(load('prod--c2pa-rs--video1.mp4')).verdict).toBe('signer_unrecognized');
  });

  test('remote credentials are not fetched', () => {
    const c = classify(load('prod--c2pa-rs--cloud.jpg'));
    expect(c.verdict).toBe('remote_not_checked');
  });

  test('a text file renamed .jpg is unsupported, not assumed to be an image', () => {
    expect(classify(load('prod--generated--not-an-image.jpg')).verdict).toBe('unsupported');
  });
});

describe('honesty rules', () => {
  const all = [
    'test--generated--ai-declared.jpg', 'test--generated--camera-capture.jpg', 'test--generated--ai-declared-tampered.jpg',
    'prod--generated--no-credentials.jpg', 'prod--c2pa-rs--CA.jpg', 'prod--c2pa-rs--cloud.jpg', 'prod--generated--not-an-image.jpg',
  ];
  test.each(all)('%s: watermark and detector are reported as not checked', (f) => {
    const c = classify(load(f));
    expect(c.checks.find((x) => x.id === 'watermark')?.state).toBe('unavailable');
    expect(c.checks.find((x) => x.id === 'detector')?.state).toBe('unavailable');
  });
  test.each(all)('%s: no percentages or probability scores', (f) => {
    const c = classify(load(f));
    expect(JSON.stringify([c.headline, c.summary, c.checks])).not.toMatch(/\d+\s?%/);
  });
  test('engine failure produces no conclusion', () => {
    const c = classify({ type: 'error', id: 'x', code: 'engine_failed', message: 'boom' });
    expect(c.verdict).toBe('failed');
    expect(c.origin).toBeNull();
  });
  test('oversized file is declined', () => {
    expect(classify({ type: 'error', id: 'x', code: 'too_large', message: '' }).verdict).toBe('too_large');
  });
});
